    const P = new Float64Array(nodes.length * 3);
    nodes.forEach((n, i) => { P[3 * i] = n[key][0]; P[3 * i + 1] = n[key][1]; P[3 * i + 2] = d === 3 ? n[key][2] ?? 0 : 0; });
    return { P, laid: false };
