  if (history.length > 100) { const k = history.findIndex((v) => !v.leave); if (k >= 0) history.splice(k, 1); }
  future.length = 0;
  navButtons();
}
function navButtons() {
  $("#back").disabled = !history.length;
  $("#fwd").disabled = !future.length;
}
function flyToView(to, toT, ms = 900) {
