function viewOf(i, dist) {
  const nd = space.nodes[i];
  const p = new THREE.Vector3(positions[3 * i], positions[3 * i + 1], positions[3 * i + 2]);
  const d = dist ?? (nd.kind === "file" ? 5 : 9);
