    const i = v.sel === null ? -1 : space.nodes.findIndex((n) => n.id === v.sel);
    if (i >= 0) showOverlay(space.nodes[i]); else closeOverlay();
    flyToView(v.pos, v.target);
    return;
  }
  const v = from.pop();
  if (!v) return;
  to.push(viewNow());
  navButtons();
  const i = v.sel === null ? -1 : space.nodes.findIndex((n) => n.id === v.sel);
