    if (hovered) setGlow(hovered, 0);
    hovered = nd;
    if (hovered) setGlow(hovered, 0.25);
    renderer.domElement.style.cursor = nd ? "pointer" : "";
    $("#hover").textContent = nd ? nd.title : "";
