      (pending && !nd.text ? `<div class="hint fetching">fetching its text…</div>` :
        `<pre class="code hljs"><code>${highlight(cut ? shown.slice(0, MAX_SHOWN).join("\n") : String(nd.text ?? ""), nd.lang ?? "")}</code></pre>`) +
