  space.nodes.forEach((m, i) => {
    if (m !== nd && m.name && !names.has(m.name)) names.set(m.name, i);
    if (m.kind === "import" || m.kind === "block") for (const n of m.names ?? []) if (n !== "*" && !names.has(n)) names.set(n, i);
