  const g = mcanvas.getContext("2d"), T = api.theme(), dark = T.fg !== "#1f2328";
  const C = dark ? { bg: "#161b22", fg: "#e6edf3", btn: "#21262d", off: "#555d66" } : { bg: "#ffffff", fg: "#1f2328", btn: "#eef1f5", off: "#a0a8b2" };
