    if (["If", "Try", "TryStar", "With", "AsyncWith"].includes(s._type) && containsDef(s)) {
      out.push({ _type: "_Head", stmt: s });
      for (const k of ["body", "orelse", "finalbody"]) out.push(...flat(s[k]));
      for (const h of s.handlers ?? []) out.push(...flat(h.body));
    } else out.push(s);
  }
